import static org.junit.Assert.*;

public class CSVParser_getHeaderMap_TriageGen1Test {

    @Test
    public void testGetHeaderMap_WithHeaders() throws IOException {
        // Arrange: Create a CSV string with a header row
        String csvContent = "id,name,age\n1,John,30\n2,Jane,25";
        CSVFormat format = CSVFormat.DEFAULT.withHeader("id", "name", "age");

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            // Act
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Assert
            assertNotNull("Header map should not be null when headers are present", headerMap);
            assertEquals("Header map size should be 3", 3, headerMap.size());
            assertEquals("Integer value for 'id' should be 0", Integer.valueOf(0), headerMap.get("id"));
            assertEquals("Integer value for 'name' should be 1", Integer.valueOf(1), headerMap.get("name"));
            assertEquals("Integer value for 'age' should be 2", Integer.valueOf(2), headerMap.get("age"));
        }
    }

    @Test
    public void testGetHeaderMap_NoHeaders() throws IOException {
        // Arrange: Create a CSV string without headers
        String csvContent = "1,John,30\n2,Jane,25";
        CSVFormat format = CSVFormat.DEFAULT; // No header defined

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            // Act
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Assert
            // Based on the implementation logic provided: return false ? null : new LinkedHashMap<>(this.headerMap);
            // If headerMap is empty inside the parser, it returns an empty map, not null.
            assertNotNull("Header map should be an empty map, not null", headerMap);
            assertTrue("Header map should be empty when no headers are defined", headerMap.isEmpty());
        }
    }

    @Test
    public void testGetHeaderMap_ReturnsNewInstance() throws IOException {
        // Arrange
        String csvContent = "id,name\n1,John";
        CSVFormat format = CSVFormat.DEFAULT.withHeader("id", "name");

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            // Act
            Map<String, Integer> firstCall = parser.getHeaderMap();
            Map<String, Integer> secondCall = parser.getHeaderMap();

            // Assert
            assertNotNull(firstCall);
            assertNotNull(secondCall);
            assertNotSame("The method should return a new instance (copy) of the map", firstCall, secondCall);
            assertEquals("The content of the maps should be identical", firstCall, secondCall);

            // Verify that modifying the returned map does not affect the parser's internal state
            firstCall.put("new_col", 99);
            assertFalse("Modifying the returned map should not affect the parser's header map", 
                    parser.getHeaderMap().containsKey("new_col"));
        }
    }
}
